// Dijital terazi: yük hücresi + HX711 ağırlığı ölçer, 16x2 LCD gram gösterir.
// Dara düğmesi o anki ağırlığı sıfır yapar.
#include <LiquidCrystal.h>
#include <HX711.h>

// Kalibrasyon katsayısı: kendi yük hücren için montaj adımlarıyla bul.
const float KALIBRASYON = 420.0;
const int ORNEK_SAYISI = 10;     // her ölçümde ortalaması alınan okuma
const float SIFIR_ESIGI = 0.5;   // g; bunun altı 0 gösterilir

const int HX_DT_PIN = 8;
const int HX_SCK_PIN = 9;
const int DARA_PIN = 7;
const int LCD_RS = 12;
const int LCD_E = 11;
const int LCD_D4 = 5;
const int LCD_D5 = 4;
const int LCD_D6 = 3;
const int LCD_D7 = 2;

LiquidCrystal lcd(LCD_RS, LCD_E, LCD_D4, LCD_D5, LCD_D6, LCD_D7);
HX711 tarti;

void daraAl() {
  lcd.clear();
  lcd.print("Dara aliniyor");
  tarti.tare(20);  // 20 okumanın ortalaması sıfır olur
  lcd.clear();
  lcd.print("Agirlik:");
  Serial.println("Dara alindi");
}

void setup() {
  Serial.begin(9600);
  pinMode(DARA_PIN, INPUT_PULLUP);
  lcd.begin(16, 2);
  tarti.begin(HX_DT_PIN, HX_SCK_PIN);

  if (!tarti.wait_ready_timeout(2000)) {
    lcd.print("HX711 yok");
    lcd.setCursor(0, 1);
    lcd.print("Kablo kontrol et");
    Serial.println("HX711 bulunamadi");
    while (true) delay(1000);
  }
  tarti.set_scale(KALIBRASYON);
  daraAl();
}

void loop() {
  // Dara düğmesi (titreşime karşı iki kez okunur).
  if (digitalRead(DARA_PIN) == LOW) {
    delay(50);
    if (digitalRead(DARA_PIN) == LOW) {
      daraAl();
      while (digitalRead(DARA_PIN) == LOW) delay(10);
    }
  }

  if (!tarti.wait_ready_timeout(500)) return;
  float gram = tarti.get_units(ORNEK_SAYISI);
  if (fabs(gram) < SIFIR_ESIGI) gram = 0;

  Serial.print("Agirlik: ");
  Serial.print(gram, 1);
  Serial.println(" g");

  // Alt satır: sağa yaslı "   123.4 g"
  char sayi[12];
  dtostrf(gram, 10, 1, sayi);
  lcd.setCursor(0, 1);
  lcd.print(sayi);
  lcd.print(" g    ");
}
